function rateLaw(k, concs, orders){ var r=k; for(var i=0;i<concs.length;i++){ r*=Math.pow(concs[i], orders[i]); } return r; }
function arrhenius(A, Ea, T, R){ R = R||8.314; if(T<=0) return NaN; return A*Math.exp(-Ea/(R*T)); }
function halfLifeFirst(k){ if(k<=0) return NaN; return Math.log(2)/k; }
function decay(N0, k, t){ return N0*Math.exp(-k*t); }
var EXPORTS={rateLaw:rateLaw, arrhenius:arrhenius, halfLifeFirst:halfLifeFirst, decay:decay};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ReactionRateForgePure = EXPORTS; }
